/* eslint-disable no-console */
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import JSZip from "jszip";
import { getStructuredRegistry } from "@enterprise-hub/domain";

/**
 * Deterministically generate the committed XLSX fixture matrix used by the
 * streaming-parser parity and pipeline tests. The files are generated by
 * hand-writing minimal OOXML so cell types (inlineStr, error, formula with or
 * without a cached value, booleans, date serials) are exactly controlled.
 */

const OUT_DIR = path.resolve("fixtures/structured/xlsx");

const NS = {
  main: "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
  relationship: "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
  packageRelationship: "http://schemas.openxmlformats.org/package/2006/relationships",
  contentTypes: "http://schemas.openxmlformats.org/package/2006/content-types"
};

const DAY_MS = 86_400_000;
const XLSX_EPOCH = Date.UTC(1899, 11, 30);
const FIXED_ZIP_DATE = new Date("2026-01-01T00:00:00Z");

function serialFor(year: number, month: number, day: number, hour = 0, minute = 0, second = 0) {
  return (Date.UTC(year, month - 1, day, hour, minute, second) - XLSX_EPOCH) / DAY_MS;
}

type Cell =
  | { k: "shared"; v: string }
  | { k: "sharedRich"; parts: string[] }
  | { k: "inline"; v: string }
  | { k: "inlineRich"; parts: string[] }
  | { k: "bool"; v: "1" | "0" }
  | { k: "num"; v: string; s?: number }
  | { k: "formula"; f: string; v?: string }
  | { k: "str"; v: string }
  | { k: "error"; v: string };

interface SheetSpec {
  name: string;
  state?: "visible" | "hidden";
  cells: Cell[][];
  hyperlinks?: Array<{ ref: string; target: string }>;
}

const DEFAULT_STYLE = 0;
const DATE_STYLE = 1;
const DATE_TIME_STYLE = 2;

function escapeXml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function textNode(value: string): string {
  const preserved = /^\s|\s$/.test(value) ? ' xml:space="preserve"' : "";
  return `<t${preserved}>${escapeXml(value)}</t>`;
}

function sharedStringXml(entries: Array<{ plain?: string; rich?: string[] }>): string {
  const items = entries
    .map((entry) => {
      if (entry.rich) {
        return `<si>${entry.rich.map((part) => `<r>${textNode(part)}</r>`).join("")}</si>`;
      }
      return `<si>${textNode(entry.plain ?? "")}</si>`;
    })
    .join("");
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<sst xmlns="${NS.main}" count="${entries.length}" uniqueCount="${entries.length}">${items}</sst>`;
}

function columnName(index: number): string {
  let name = "";
  let value = index;
  while (value >= 0) {
    name = String.fromCharCode(65 + (value % 26)) + name;
    value = Math.floor(value / 26) - 1;
  }
  return name;
}

function sheetXml(
  spec: SheetSpec,
  sharedStrings: Array<{ plain?: string; rich?: string[] }>
): string {
  const rows = spec.cells
    .map((cells, rowIndex) => {
      const rowNumber = rowIndex + 1;
      const rendered = cells
        .map((cell, columnIndex) => {
          const ref = `${columnName(columnIndex)}${rowNumber}`;
          const style = "s" in cell && cell.s ? ` s="${cell.s}"` : "";
          switch (cell.k) {
            case "shared": {
              const index = sharedStrings.findIndex((entry) => entry.plain === cell.v);
              return `<c r="${ref}" t="s"${style}><v>${index}</v></c>`;
            }
            case "sharedRich": {
              const index = sharedStrings.findIndex(
                (entry) =>
                  entry.rich !== undefined &&
                  entry.rich.length === cell.parts.length &&
                  entry.rich.every((part, partIndex) => part === cell.parts[partIndex])
              );
              return `<c r="${ref}" t="s"${style}><v>${index}</v></c>`;
            }
            case "inline":
              return `<c r="${ref}" t="inlineStr"${style}><is>${textNode(cell.v)}</is></c>`;
            case "inlineRich":
              return `<c r="${ref}" t="inlineStr"${style}><is>${cell.parts
                .map((part) => `<r>${textNode(part)}</r>`)
                .join("")}</is></c>`;
            case "bool":
              return `<c r="${ref}" t="b"${style}><v>${cell.v}</v></c>`;
            case "num":
              return `<c r="${ref}" t="n"${style}><v>${cell.v}</v></c>`;
            case "formula": {
              const value = cell.v === undefined ? "" : `<v>${cell.v}</v>`;
              return `<c r="${ref}"${style}><f>${escapeXml(cell.f)}</f>${value}</c>`;
            }
            case "str":
              return `<c r="${ref}" t="str"${style}><v>${escapeXml(cell.v)}</v></c>`;
            case "error":
              return `<c r="${ref}" t="e"${style}><v>${escapeXml(cell.v)}</v></c>`;
          }
        })
        .join("");
      return `<row r="${rowNumber}">${rendered}</row>`;
    })
    .join("");

  const hyperlinks = (spec.hyperlinks ?? [])
    .map((hyperlink, index) => `<hyperlink ref="${hyperlink.ref}" r:id="rIdH${index + 1}"/>`)
    .join("");

  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="${NS.main}" xmlns:r="${NS.relationship}">
  <sheetData>${rows}</sheetData>${hyperlinks ? `<hyperlinks>${hyperlinks}</hyperlinks>` : ""}
</worksheet>`;
}

function stylesXml(useCustomDateFormats: boolean): string {
  const numFmts = useCustomDateFormats
    ? `<numFmts count="2"><numFmt numFmtId="164" formatCode="yyyy-mm-dd"/><numFmt numFmtId="165" formatCode="yyyy-mm-dd hh:mm:ss"/></numFmts>`
    : "";
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="${NS.main}">${numFmts}
  <fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts>
  <fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>
  <borders count="1"><border/></borders>
  <cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
  <cellXfs count="3">
    <xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>
    <xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/>
    <xf numFmtId="165" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/>
  </cellXfs>
</styleSheet>`;
}

async function buildWorkbook(sheets: SheetSpec[]): Promise<Buffer> {
  const sharedStrings: Array<{ plain?: string; rich?: string[] }> = [];
  for (const sheet of sheets) {
    for (const cells of sheet.cells) {
      for (const cell of cells) {
        if (cell.k === "shared") {
          if (!sharedStrings.some((entry) => entry.plain === cell.v)) {
            sharedStrings.push({ plain: cell.v });
          }
        } else if (cell.k === "sharedRich") {
          const matches = (entry: { plain?: string; rich?: string[] }) =>
            entry.rich !== undefined &&
            entry.rich.length === cell.parts.length &&
            entry.rich.every((part, index) => part === cell.parts[index]);
          if (!sharedStrings.some(matches)) {
            sharedStrings.push({ rich: [...cell.parts] });
          }
        }
      }
    }
  }

  const useCustomDateFormats = sheets.some((sheet) =>
    sheet.cells.some((cells) =>
      cells.some((cell) => "s" in cell && cell.s && cell.s > DEFAULT_STYLE)
    )
  );

  const zip = new JSZip();

  const sheetFiles = sheets.map((sheet, index) => ({
    file: `xl/worksheets/sheet${index + 1}.xml`,
    xml: sheetXml(sheet, sharedStrings)
  }));
  const sheetRelsFiles = sheets
    .map((sheet, index) => {
      const hyperlinks = sheet.hyperlinks ?? [];
      if (hyperlinks.length === 0) return null;
      const relationships = hyperlinks
        .map(
          (hyperlink, hyperlinkIndex) =>
            `<Relationship Id="rIdH${hyperlinkIndex + 1}" Type="${NS.relationship}/hyperlink" Target="${escapeXml(hyperlink.target)}" TargetMode="External"/>`
        )
        .join("");
      return {
        file: `xl/worksheets/_rels/sheet${index + 1}.xml.rels`,
        xml: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="${NS.packageRelationship}">${relationships}</Relationships>`
      };
    })
    .filter((entry): entry is NonNullable<typeof entry> => entry !== null);

  const sharedStringsFile = sharedStrings.length
    ? [{ file: "xl/sharedStrings.xml", xml: sharedStringXml(sharedStrings) }]
    : [];
  const stylesFile = [{ file: "xl/styles.xml", xml: stylesXml(useCustomDateFormats) }];

  const sheetEntries = sheets
    .map(
      (sheet, index) =>
        `<sheet name="${escapeXml(sheet.name)}" sheetId="${index + 1}"${
          sheet.state === "hidden" ? ' state="hidden"' : ""
        } r:id="rId${index + 1}"/>`
    )
    .join("");

  const workbookXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="${NS.main}" xmlns:r="${NS.relationship}">
  <sheets>${sheetEntries}</sheets>
</workbook>`;

  const workbookRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="${NS.packageRelationship}">
  ${sheets
    .map(
      (_, index) =>
        `<Relationship Id="rId${index + 1}" Type="${NS.relationship}/worksheet" Target="worksheets/sheet${index + 1}.xml"/>`
    )
    .join("")}
  ${
    sharedStringsFile.length
      ? `<Relationship Id="rIdS" Type="${NS.relationship}/sharedStrings" Target="sharedStrings.xml"/>`
      : ""
  }
  <Relationship Id="rIdT" Type="${NS.relationship}/styles" Target="styles.xml"/>
</Relationships>`;

  const contentTypes = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="${NS.contentTypes}">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
  ${sheets
    .map(
      (_, index) =>
        `<Override PartName="/xl/worksheets/sheet${index + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`
    )
    .join("")}
  ${
    sharedStringsFile.length
      ? '<Override PartName="/xl/sharedStrings.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"/>'
      : ""
  }
  <Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>
</Types>`;

  zip.file("[Content_Types].xml", contentTypes, { date: FIXED_ZIP_DATE });
  const rootRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="${NS.packageRelationship}">
  <Relationship Id="rId1" Type="${NS.relationship}/officeDocument" Target="xl/workbook.xml"/>
</Relationships>`;
  zip.file("_rels/.rels", rootRels, { date: FIXED_ZIP_DATE });
  zip.file("xl/workbook.xml", workbookXml, { date: FIXED_ZIP_DATE });
  zip.file("xl/_rels/workbook.xml.rels", workbookRels, { date: FIXED_ZIP_DATE });
  for (const entry of sheetFiles) zip.file(entry.file, entry.xml, { date: FIXED_ZIP_DATE });
  for (const entry of sheetRelsFiles) zip.file(entry.file, entry.xml, { date: FIXED_ZIP_DATE });
  for (const entry of sharedStringsFile) zip.file(entry.file, entry.xml, { date: FIXED_ZIP_DATE });
  for (const entry of stylesFile) zip.file(entry.file, entry.xml, { date: FIXED_ZIP_DATE });

  // JSZip also materializes directory entries (for example `xl/`) with the
  // current time; pin every entry, including directories, for deterministic output.
  for (const entry of Object.values(zip.files)) {
    entry.date = FIXED_ZIP_DATE;
  }

  return zip.generateAsync({ type: "nodebuffer", compression: "DEFLATE" });
}

function dishesHeaders(): string[] {
  return getStructuredRegistry("dishes").fields.map((field) => field.sourceColumn);
}

function headerRow(): Cell[] {
  return dishesHeaders().map((header) => ({ k: "shared", v: header }));
}

function baseDataRow(): Cell[] {
  return dishesHeaders().map(() => ({ k: "shared", v: "" }));
}

function setCell(row: Cell[], headers: string[], sourceColumn: string, cell: Cell): void {
  const index = headers.indexOf(sourceColumn);
  if (index < 0) throw new Error(`Unknown source column: ${sourceColumn}`);
  row[index] = cell;
}

function dishesWorkbook(sheets: SheetSpec[]): Promise<Buffer> {
  return buildWorkbook(sheets);
}

async function writeFixture(fileName: string, content: Buffer | Promise<Buffer>): Promise<void> {
  await mkdir(OUT_DIR, { recursive: true });
  const bytes = await content;
  await writeFile(path.join(OUT_DIR, fileName), bytes);
  console.log(`${fileName}: ${bytes.byteLength} bytes`);
}

async function main(): Promise<void> {
  const headers = dishesHeaders();

  // typed-cells.xlsx: one dataset-valid row exercising every cell type.
  {
    const row = baseDataRow();
    setCell(row, headers, "菜品名称", { k: "sharedRich", parts: ["Rich ", "product"] });
    setCell(row, headers, "门店", { k: "shared", v: "Linked Store" });
    setCell(row, headers, "营业日", {
      k: "num",
      v: String(serialFor(2026, 7, 1)),
      s: DATE_STYLE
    });
    setCell(row, headers, "下单时间", {
      k: "num",
      v: String(serialFor(2026, 7, 1, 12, 30, 45)),
      s: DATE_TIME_STYLE
    });
    setCell(row, headers, "菜品销售数量", { k: "formula", f: "1+2", v: "3" });
    setCell(row, headers, "是否是会员", { k: "bool", v: "1" });
    setCell(row, headers, "关联菜品名称", { k: "inline", v: "Inline product" });
    setCell(row, headers, "订单分类", { k: "str", v: "堂食" });
    setCell(row, headers, "菜品销售额", { k: "num", v: "10.5" });
    await writeFixture(
      "typed-cells.xlsx",
      dishesWorkbook([
        {
          name: "Data",
          cells: [headerRow(), row],
          hyperlinks: [{ ref: "B2", target: "https://example.test/store" }]
        }
      ])
    );
  }

  // unevaluated-formula.xlsx: <f> without a cached <v>.
  {
    const row = baseDataRow();
    setCell(row, headers, "营业日", { k: "shared", v: "2026-07-01" });
    setCell(row, headers, "菜品名称", { k: "formula", f: "1+1" });
    await writeFixture(
      "unevaluated-formula.xlsx",
      dishesWorkbook([{ name: "Data", cells: [headerRow(), row] }])
    );
  }

  // error-cell.xlsx: t="e" cell.
  {
    const row = baseDataRow();
    setCell(row, headers, "营业日", { k: "shared", v: "2026-07-01" });
    setCell(row, headers, "门店", { k: "error", v: "#DIV/0!" });
    await writeFixture(
      "error-cell.xlsx",
      dishesWorkbook([{ name: "Data", cells: [headerRow(), row] }])
    );
  }

  // sparse-rows.xlsx: data at rows 2 and 6, rows 3-5 omitted.
  {
    const rowA = baseDataRow();
    setCell(rowA, headers, "营业日", { k: "shared", v: "2026-07-01" });
    setCell(rowA, headers, "菜品名称", { k: "shared", v: "Alpha" });
    const rowB = baseDataRow();
    setCell(rowB, headers, "营业日", { k: "shared", v: "2026-07-02" });
    setCell(rowB, headers, "菜品名称", { k: "shared", v: "Beta" });
    await writeFixture(
      "sparse-rows.xlsx",
      dishesWorkbook([
        {
          name: "Data",
          cells: [headerRow(), rowA, [], [], [], rowB]
        }
      ])
    );
  }

  // hidden-sheet.xlsx: hidden non-empty sheet.
  {
    const row = baseDataRow();
    setCell(row, headers, "营业日", { k: "shared", v: "2026-07-01" });
    await writeFixture(
      "hidden-sheet.xlsx",
      dishesWorkbook([
        { name: "Data", cells: [headerRow()] },
        { name: "HiddenData", state: "hidden", cells: [headerRow(), row] }
      ])
    );
  }

  // cross-sheet.xlsx: two sheets whose combined rows exceed a limit of one.
  {
    const row = baseDataRow();
    setCell(row, headers, "营业日", { k: "shared", v: "2026-07-01" });
    await writeFixture(
      "cross-sheet.xlsx",
      dishesWorkbook([
        { name: "First", cells: [headerRow(), row] },
        { name: "Second", cells: [headerRow(), row] }
      ])
    );
  }

  // multi-sheet-visible.xlsx: sheet order must be preserved.
  {
    const first = baseDataRow();
    setCell(first, headers, "营业日", { k: "shared", v: "2026-07-01" });
    setCell(first, headers, "菜品名称", { k: "shared", v: "First" });
    const second = baseDataRow();
    setCell(second, headers, "营业日", { k: "shared", v: "2026-07-02" });
    setCell(second, headers, "菜品名称", { k: "shared", v: "Second" });
    await writeFixture(
      "multi-sheet-visible.xlsx",
      dishesWorkbook([
        { name: "First", cells: [headerRow(), first] },
        { name: "Second", cells: [headerRow(), second] }
      ])
    );
  }

  // date-serials.xlsx: Excel serial boundary (1900 leap bug) and time fractions.
  {
    const boundarySerials = [59, 60, 61, 62, serialFor(2026, 7, 1)];
    const rows = boundarySerials.map((serial) => {
      const row = baseDataRow();
      setCell(row, headers, "营业日", { k: "num", v: String(serial), s: DATE_STYLE });
      return row;
    });
    const timeRow = baseDataRow();
    setCell(timeRow, headers, "营业日", { k: "shared", v: "2026-07-01" });
    setCell(timeRow, headers, "下单时间", {
      k: "num",
      v: String(serialFor(2026, 7, 1, 23, 59, 59) + 0.999),
      s: DATE_TIME_STYLE
    });
    rows.push(timeRow);
    await writeFixture(
      "date-serials.xlsx",
      dishesWorkbook([{ name: "Data", cells: [headerRow(), ...rows] }])
    );
  }

  console.log("Generated", OUT_DIR);
}

main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});
